INSERT INTO documents(id,kind,course_id,draft,revision,published,published_revision,review,updated_at,published_review) VALUES('confidence-intervals','lesson','cs1-inference','{"id": "confidence-intervals", "courseId": "cs1-inference", "title": "A confidence interval is a procedure", "subtitle": "The parameter stays fixed. The interval moves.", "minutes": 25, "prerequisites": ["Mean and standard error of an independent sample mean.", "Normal probabilities and symmetry; population standard deviation is treated as known."], "outcomes": ["Derive a known-variance normal mean interval from a pivot.", "Explain coverage without assigning a frequentist probability to a fixed parameter after observation.", "Predict how sample size and confidence level affect interval width."], "objectiveIds": ["3.2.1", "3.2.2.normal-known", "3.2.3.mean-known"], "scopeNote": "Selected historical CS1 scope only. Known population standard deviation is assumed; estimating it requires methods beyond this unit.", "blocks": [{"id": "ci-opening", "type": "callout", "title": "A point estimate is only the beginning", "text": "A sample mean is useful, but another sample would produce another value. An interval adds information about the uncertainty of a procedure. It does not turn a model assumption into an observed fact.", "tone": "idea", "objectives": []}, {"id": "ci-model-heading", "type": "heading", "text": "Specify the experiment before the percentage", "level": 2}, {"id": "ci-model", "type": "prose", "text": "Assume $X_1,\\ldots,X_n$ are independent normal observations with unknown mean $\\mu$ and known population standard deviation $\\sigma$. Then $\\bar X$ is exactly normal with mean $\\mu$ and standard error $\\sigma/\\sqrt n$. We use the data to produce a random interval whose construction is designed to contain the fixed parameter in a stated proportion of repeated samples.\n\nA confidence level such as 95% describes the long-run coverage of that construction under the model. It is not a guarantee for the particular sample in hand. Changing the population, sampling design or model can change coverage even when a formula still displays \u201c95%\u201d.", "objectives": ["3.2.1"]}, {"id": "ci-pivot", "type": "prose", "text": "The standardised quantity $Z=(\\bar X-\\mu)/(\\sigma/\\sqrt n)$ has a standard normal distribution under this model. Let $z_{1-\\alpha/2}$ be the normal quantile leaving probability \u03b1/2 above it. Symmetry gives probability 1\u2212\u03b1 between the negative and positive quantiles. We now rearrange that probability statement to isolate \u03bc.", "objectives": ["3.2.2.normal-known"]}, {"id": "ci-derivation", "type": "worked", "title": "Turn a probability statement into random endpoints", "objectives": ["3.2.2.normal-known"], "steps": [{"title": "Begin with a distribution we know", "text": "P(\u2212z \u2264 (X\u0304\u2212\u03bc)/(\u03c3/\u221an) \u2264 z) = 1\u2212\u03b1, with z = z\u2081\u208b\u03b1/\u2082.", "why": "The pivot has a distribution that does not depend on the unknown mean."}, {"title": "Use a positive scale", "text": "Multiply the inequalities by \u03c3/\u221an, which is positive, so their directions remain unchanged.", "why": "The parameter domain and sample size make the scale positive."}, {"title": "Isolate the parameter", "text": "The event is equivalent to X\u0304\u2212z\u03c3/\u221an \u2264 \u03bc \u2264 X\u0304+z\u03c3/\u221an.", "why": "The endpoints are random because they depend on the random sample mean."}, {"title": "Observe the data", "text": "Substitute the realised sample mean to obtain one numerical interval. The construction had coverage 1\u2212\u03b1 before seeing the sample.", "why": "After observation the parameter and both realised endpoints are fixed in this frequentist model."}]}, {"id": "ci-formula", "type": "math", "tex": "\\left[\\bar x-z_{1-\\alpha/2}\\frac{\\sigma}{\\sqrt n},\\ \\bar x+z_{1-\\alpha/2}\\frac{\\sigma}{\\sqrt n}\\right]", "explanation": "Centre the interval on the observed mean. The margin is a normal quantile multiplied by the standard error.", "objectives": ["3.2.2.normal-known", "3.2.3.mean-known"]}, {"id": "ci-misconception", "type": "callout", "title": "Where the 95% belongs", "text": "Once the numerical interval is observed, it either contains the fixed mean or it does not. The 95% refers to the performance of the interval-generating procedure over repeated samples. A probability distribution for \u03bc after seeing data would require a different modelling framework; it does not follow from this frequentist calculation.", "tone": "warning", "objectives": ["3.2.1"]}, {"id": "ci-example", "type": "worked", "title": "A processing-cost interval", "objectives": ["3.2.3.mean-known"], "steps": [{"title": "State the inputs", "text": "For an independent normal sample of n = 25 costs, suppose x\u0304 = 104 and the known population standard deviation is 20. Use 95% confidence.", "why": "The known population standard deviation is an assumption, not a value estimated from these 25 records."}, {"title": "Compute the standard error", "text": "20 / \u221a25 = 4 currency units. The 0.975 normal quantile is about 1.959964.", "why": "Each tail has 0.025 probability under the standard normal model."}, {"title": "Form the interval", "text": "The margin is 1.959964 \u00d7 4 = 7.839856. The interval is [96.160144, 111.839856], or [96.16, 111.84] to two decimal places.", "why": "The endpoints, not just the centre, must use consistent units and rounding."}, {"title": "Interpret and check", "text": "This is one interval generated by a procedure with 95% coverage under the stated model. Its length is 15.679712 currency units.", "why": "The interval does not contain 95% of individual costs; it targets a population mean."}]}, {"id": "ci-calculate", "type": "question", "prompt": "An independent normal sample has observed mean 52, known population standard deviation 12, and n = 36. Using z = 1.96, what is the lower endpoint of the 95% confidence interval?", "solution": "Standard error = 12/\u221a36 = 2. Margin = 1.96\u00d72 = 3.92. The lower endpoint is 52\u22123.92 = 48.08. The corresponding upper endpoint is 55.92.", "taughtIn": ["ci-formula", "ci-example"], "objectives": ["3.2.2.normal-known", "3.2.3.mean-known"], "questionKind": "numeric", "answer": 48.08, "tolerance": 0.005, "unit": "currency units", "hints": ["Find the standard error first.", "A lower endpoint subtracts the margin from the observed mean."]}, {"id": "ci-reconstruct", "type": "question", "questionKind": "written", "objectives": ["3.2.2.normal-known"], "prompt": "For independent normal observations with unknown mean \u03bc and known \u03c3>0, derive a two-sided (1\u2212\u03b1) confidence interval for \u03bc. Start from the standard normal pivot, show the inequality rearrangement, and identify which quantities are random before sampling.", "taughtIn": ["ci-model", "ci-pivot", "ci-derivation", "ci-formula"], "solution": "Under the model, Z=(X\u0304\u2212\u03bc)/(\u03c3/\u221an) has a standard normal distribution. Put z=z\u2081\u208b\u03b1/\u2082. Then P(\u2212z\u2264(X\u0304\u2212\u03bc)/(\u03c3/\u221an)\u2264z)=1\u2212\u03b1. Multiplying by the positive standard error gives the equivalent event \u2212z\u03c3/\u221an\u2264X\u0304\u2212\u03bc\u2264z\u03c3/\u221an. Rearranging yields X\u0304\u2212z\u03c3/\u221an\u2264\u03bc\u2264X\u0304+z\u03c3/\u221an. Therefore the two endpoints define a random interval with coverage 1\u2212\u03b1 under the model. The endpoints depend on X\u0304 and are random before sampling; \u03bc is fixed. Observing x\u0304 yields numerical endpoints without assigning a frequentist posterior probability to \u03bc.", "rubric": [{"text": "Specify the standard normal pivot and its model assumptions.", "marks": 2, "taughtIn": ["ci-model", "ci-pivot"]}, {"text": "Allocate \u03b1/2 to each tail and state the central probability event.", "marks": 2, "taughtIn": ["ci-pivot", "ci-derivation"]}, {"text": "Rearrange using the positive scale to obtain both correct endpoints.", "marks": 2, "taughtIn": ["ci-derivation", "ci-formula"]}, {"text": "Identify the random endpoints and fixed parameter before sampling.", "marks": 2, "taughtIn": ["ci-model", "ci-derivation"]}]}, {"id": "ci-width-heading", "type": "heading", "text": "Coverage and precision answer different questions", "level": 2}, {"id": "ci-width", "type": "prose", "text": "The interval length is $2z_{1-\\alpha/2}\\sigma/\\sqrt n$. With the same \u03c3 and confidence level, increasing n from 25 to 100 halves the length. Increasing the confidence level instead requires a larger quantile, so it widens the interval. A narrower interval is not automatically a better statement if it achieves that narrowness by reducing coverage or ignoring important uncertainty.\n\nFor our exact model, a 99% procedure covers the mean more often in repeated samples than a 90% procedure, at the cost of wider intervals. Neither procedure makes a biased sampling design representative. If \u03c3 is unknown, replacing it with a sample standard deviation changes the pivot; the appropriate t method is outside this unit.", "objectives": ["3.2.1", "3.2.3.mean-known"]}, {"id": "coverage-lab", "type": "lab", "labKind": "coverage", "title": "Watch the interval move, not the parameter", "objectives": ["3.2.1", "3.2.3.mean-known"], "purpose": "Separate the fixed true mean from the random intervals created by repeated normal samples.", "prediction": "Predict how many of 50 independently generated 95% intervals will miss the true mean. Must it be exactly two or three?", "debrief": "The miss count is itself random. A finite batch need not achieve exactly the nominal coverage. The fixed vertical line marks the true mean; endpoints move because samples change.", "fallback": "With known \u03c3=20 and n=25, every 95% interval has theoretical length about 15.68. Repeating the procedure 50 times produces an expected 47.5 covering intervals, not a guaranteed count. The true mean does not move between repetitions.", "transfer": "Explain what would happen to interval length and long-run coverage if n quadrupled but the nominal confidence level stayed fixed."}, {"id": "ci-interpret", "type": "question", "prompt": "After computing [96.16, 111.84], which statement matches the frequentist model?", "solution": "The interval is one realised output of a method with 95% repeated-sampling coverage under the model. Individual costs are not its target, and no posterior probability for the fixed mean has been specified.", "taughtIn": ["ci-model", "ci-derivation", "ci-misconception", "coverage-lab"], "objectives": ["3.2.1"], "questionKind": "choice", "options": ["95% of individual processing costs lie inside these endpoints.", "The fixed mean has a 95% frequentist probability of being inside these now-fixed endpoints.", "The interval came from a procedure that covers the fixed mean in 95% of repeated samples under the model."], "correct": 2, "feedback": ["A confidence interval for a mean does not estimate an interval containing 95% of individuals.", "That probability interpretation would require an additional model for the parameter; it is not this calculation.", "Yes. Coverage describes the procedure before observing a particular sample."]}, {"id": "ci-transfer", "type": "question", "prompt": "A manager wants both shorter intervals and higher confidence. Explain why changing confidence alone cannot achieve both, and identify one model-preserving way to improve precision.", "solution": "Higher confidence increases the quantile and therefore widens the interval at fixed n and \u03c3. Increasing the size of a genuinely independent representative sample reduces standard error and can offset that width increase. It does not repair selection bias.", "taughtIn": ["ci-width", "ci-model"], "objectives": ["3.2.1", "3.2.3.mean-known"], "questionKind": "written", "rubric": [{"text": "Link higher confidence to a larger quantile and greater width.", "marks": 2, "taughtIn": ["ci-width"]}, {"text": "Explain how increasing a valid sample size reduces standard error, without claiming bias is fixed.", "marks": 2, "taughtIn": ["ci-width", "ci-model"]}]}, {"id": "ci-readiness", "type": "callout", "title": "Choose a repair, then retry", "tone": "idea", "text": "If you described 95% of individual costs, return to \u201cWhere the 95% belongs\u201d. If you assigned 95% frequentist probability to the fixed mean after observing endpoints, revisit the random-endpoint derivation and coverage lab. If higher confidence made your interval narrower, revisit \u201cCoverage and precision answer different questions\u201d. Retry without the displayed formula: independent normal data have known \u03c3=10, n=25 and observed mean 50. Using z=1.96 gives SE=2 and interval [46.08,53.92]. Explain why quadrupling n halves the width while leaving the model\u2019s nominal coverage at 95%. Reading these endpoints is not evidence that you can reconstruct their derivation."}], "summary": ["A confidence interval is a random procedure before sampling and fixed endpoints after observation.", "The known-variance normal mean interval follows by rearranging a standard normal pivot.", "More confidence widens an interval; larger independent samples narrow it.", "The advertised coverage depends on the model and sampling plan."], "coverage": [{"objective": "3.2.1", "teaching": ["ci-model", "ci-misconception"], "practice": ["ci-interpret", "ci-transfer"]}, {"objective": "3.2.2.normal-known", "teaching": ["ci-pivot", "ci-derivation"], "practice": ["ci-calculate", "ci-reconstruct"]}, {"objective": "3.2.3.mean-known", "teaching": ["ci-formula", "ci-example", "ci-width"], "practice": ["ci-calculate", "ci-transfer"]}], "provenance": "Original prose, fictional situations, numerical designs, questions and interaction brief created independently for Open Actuary. The supplied 2019 syllabus identifies scope; no ActEd text, fictional case, exercise or diagram is reproduced.", "technicalNotes": ["Normal quantiles and endpoints are checked against independent reference values.", "Simulation counts are stochastic illustrations; the coverage probability follows from the pivot.", "Known variance and exact normality are maintained in this unit; no t or bootstrap claim is made."]}','2','{"id": "confidence-intervals", "courseId": "cs1-inference", "title": "A confidence interval is a procedure", "subtitle": "The parameter stays fixed. The interval moves.", "minutes": 25, "prerequisites": ["Mean and standard error of an independent sample mean.", "Normal probabilities and symmetry; population standard deviation is treated as known."], "outcomes": ["Derive a known-variance normal mean interval from a pivot.", "Explain coverage without assigning a frequentist probability to a fixed parameter after observation.", "Predict how sample size and confidence level affect interval width."], "objectiveIds": ["3.2.1", "3.2.2.normal-known", "3.2.3.mean-known"], "scopeNote": "Selected historical CS1 scope only. Known population standard deviation is assumed; estimating it requires methods beyond this unit.", "blocks": [{"id": "ci-opening", "type": "callout", "title": "A point estimate is only the beginning", "text": "A sample mean is useful, but another sample would produce another value. An interval adds information about the uncertainty of a procedure. It does not turn a model assumption into an observed fact.", "tone": "idea", "objectives": []}, {"id": "ci-model-heading", "type": "heading", "text": "Specify the experiment before the percentage", "level": 2}, {"id": "ci-model", "type": "prose", "text": "Assume $X_1,\\ldots,X_n$ are independent normal observations with unknown mean $\\mu$ and known population standard deviation $\\sigma$. Then $\\bar X$ is exactly normal with mean $\\mu$ and standard error $\\sigma/\\sqrt n$. We use the data to produce a random interval whose construction is designed to contain the fixed parameter in a stated proportion of repeated samples.\n\nA confidence level such as 95% describes the long-run coverage of that construction under the model. It is not a guarantee for the particular sample in hand. Changing the population, sampling design or model can change coverage even when a formula still displays \u201c95%\u201d.", "objectives": ["3.2.1"]}, {"id": "ci-pivot", "type": "prose", "text": "The standardised quantity $Z=(\\bar X-\\mu)/(\\sigma/\\sqrt n)$ has a standard normal distribution under this model. Let $z_{1-\\alpha/2}$ be the normal quantile leaving probability \u03b1/2 above it. Symmetry gives probability 1\u2212\u03b1 between the negative and positive quantiles. We now rearrange that probability statement to isolate \u03bc.", "objectives": ["3.2.2.normal-known"]}, {"id": "ci-derivation", "type": "worked", "title": "Turn a probability statement into random endpoints", "objectives": ["3.2.2.normal-known"], "steps": [{"title": "Begin with a distribution we know", "text": "P(\u2212z \u2264 (X\u0304\u2212\u03bc)/(\u03c3/\u221an) \u2264 z) = 1\u2212\u03b1, with z = z\u2081\u208b\u03b1/\u2082.", "why": "The pivot has a distribution that does not depend on the unknown mean."}, {"title": "Use a positive scale", "text": "Multiply the inequalities by \u03c3/\u221an, which is positive, so their directions remain unchanged.", "why": "The parameter domain and sample size make the scale positive."}, {"title": "Isolate the parameter", "text": "The event is equivalent to X\u0304\u2212z\u03c3/\u221an \u2264 \u03bc \u2264 X\u0304+z\u03c3/\u221an.", "why": "The endpoints are random because they depend on the random sample mean."}, {"title": "Observe the data", "text": "Substitute the realised sample mean to obtain one numerical interval. The construction had coverage 1\u2212\u03b1 before seeing the sample.", "why": "After observation the parameter and both realised endpoints are fixed in this frequentist model."}]}, {"id": "ci-formula", "type": "math", "tex": "\\left[\\bar x-z_{1-\\alpha/2}\\frac{\\sigma}{\\sqrt n},\\ \\bar x+z_{1-\\alpha/2}\\frac{\\sigma}{\\sqrt n}\\right]", "explanation": "Centre the interval on the observed mean. The margin is a normal quantile multiplied by the standard error.", "objectives": ["3.2.2.normal-known", "3.2.3.mean-known"]}, {"id": "ci-misconception", "type": "callout", "title": "Where the 95% belongs", "text": "Once the numerical interval is observed, it either contains the fixed mean or it does not. The 95% refers to the performance of the interval-generating procedure over repeated samples. A probability distribution for \u03bc after seeing data would require a different modelling framework; it does not follow from this frequentist calculation.", "tone": "warning", "objectives": ["3.2.1"]}, {"id": "ci-example", "type": "worked", "title": "A processing-cost interval", "objectives": ["3.2.3.mean-known"], "steps": [{"title": "State the inputs", "text": "For an independent normal sample of n = 25 costs, suppose x\u0304 = 104 and the known population standard deviation is 20. Use 95% confidence.", "why": "The known population standard deviation is an assumption, not a value estimated from these 25 records."}, {"title": "Compute the standard error", "text": "20 / \u221a25 = 4 currency units. The 0.975 normal quantile is about 1.959964.", "why": "Each tail has 0.025 probability under the standard normal model."}, {"title": "Form the interval", "text": "The margin is 1.959964 \u00d7 4 = 7.839856. The interval is [96.160144, 111.839856], or [96.16, 111.84] to two decimal places.", "why": "The endpoints, not just the centre, must use consistent units and rounding."}, {"title": "Interpret and check", "text": "This is one interval generated by a procedure with 95% coverage under the stated model. Its length is 15.679712 currency units.", "why": "The interval does not contain 95% of individual costs; it targets a population mean."}]}, {"id": "ci-calculate", "type": "question", "prompt": "An independent normal sample has observed mean 52, known population standard deviation 12, and n = 36. Using z = 1.96, what is the lower endpoint of the 95% confidence interval?", "solution": "Standard error = 12/\u221a36 = 2. Margin = 1.96\u00d72 = 3.92. The lower endpoint is 52\u22123.92 = 48.08. The corresponding upper endpoint is 55.92.", "taughtIn": ["ci-formula", "ci-example"], "objectives": ["3.2.2.normal-known", "3.2.3.mean-known"], "questionKind": "numeric", "answer": 48.08, "tolerance": 0.005, "unit": "currency units", "hints": ["Find the standard error first.", "A lower endpoint subtracts the margin from the observed mean."]}, {"id": "ci-reconstruct", "type": "question", "questionKind": "written", "objectives": ["3.2.2.normal-known"], "prompt": "For independent normal observations with unknown mean \u03bc and known \u03c3>0, derive a two-sided (1\u2212\u03b1) confidence interval for \u03bc. Start from the standard normal pivot, show the inequality rearrangement, and identify which quantities are random before sampling.", "taughtIn": ["ci-model", "ci-pivot", "ci-derivation", "ci-formula"], "solution": "Under the model, Z=(X\u0304\u2212\u03bc)/(\u03c3/\u221an) has a standard normal distribution. Put z=z\u2081\u208b\u03b1/\u2082. Then P(\u2212z\u2264(X\u0304\u2212\u03bc)/(\u03c3/\u221an)\u2264z)=1\u2212\u03b1. Multiplying by the positive standard error gives the equivalent event \u2212z\u03c3/\u221an\u2264X\u0304\u2212\u03bc\u2264z\u03c3/\u221an. Rearranging yields X\u0304\u2212z\u03c3/\u221an\u2264\u03bc\u2264X\u0304+z\u03c3/\u221an. Therefore the two endpoints define a random interval with coverage 1\u2212\u03b1 under the model. The endpoints depend on X\u0304 and are random before sampling; \u03bc is fixed. Observing x\u0304 yields numerical endpoints without assigning a frequentist posterior probability to \u03bc.", "rubric": [{"text": "Specify the standard normal pivot and its model assumptions.", "marks": 2, "taughtIn": ["ci-model", "ci-pivot"]}, {"text": "Allocate \u03b1/2 to each tail and state the central probability event.", "marks": 2, "taughtIn": ["ci-pivot", "ci-derivation"]}, {"text": "Rearrange using the positive scale to obtain both correct endpoints.", "marks": 2, "taughtIn": ["ci-derivation", "ci-formula"]}, {"text": "Identify the random endpoints and fixed parameter before sampling.", "marks": 2, "taughtIn": ["ci-model", "ci-derivation"]}]}, {"id": "ci-width-heading", "type": "heading", "text": "Coverage and precision answer different questions", "level": 2}, {"id": "ci-width", "type": "prose", "text": "The interval length is $2z_{1-\\alpha/2}\\sigma/\\sqrt n$. With the same \u03c3 and confidence level, increasing n from 25 to 100 halves the length. Increasing the confidence level instead requires a larger quantile, so it widens the interval. A narrower interval is not automatically a better statement if it achieves that narrowness by reducing coverage or ignoring important uncertainty.\n\nFor our exact model, a 99% procedure covers the mean more often in repeated samples than a 90% procedure, at the cost of wider intervals. Neither procedure makes a biased sampling design representative. If \u03c3 is unknown, replacing it with a sample standard deviation changes the pivot; the appropriate t method is outside this unit.", "objectives": ["3.2.1", "3.2.3.mean-known"]}, {"id": "coverage-lab", "type": "lab", "labKind": "coverage", "title": "Watch the interval move, not the parameter", "objectives": ["3.2.1", "3.2.3.mean-known"], "purpose": "Separate the fixed true mean from the random intervals created by repeated normal samples.", "prediction": "Predict how many of 50 independently generated 95% intervals will miss the true mean. Must it be exactly two or three?", "debrief": "The miss count is itself random. A finite batch need not achieve exactly the nominal coverage. The fixed vertical line marks the true mean; endpoints move because samples change.", "fallback": "With known \u03c3=20 and n=25, every 95% interval has theoretical length about 15.68. Repeating the procedure 50 times produces an expected 47.5 covering intervals, not a guaranteed count. The true mean does not move between repetitions.", "transfer": "Explain what would happen to interval length and long-run coverage if n quadrupled but the nominal confidence level stayed fixed."}, {"id": "ci-interpret", "type": "question", "prompt": "After computing [96.16, 111.84], which statement matches the frequentist model?", "solution": "The interval is one realised output of a method with 95% repeated-sampling coverage under the model. Individual costs are not its target, and no posterior probability for the fixed mean has been specified.", "taughtIn": ["ci-model", "ci-derivation", "ci-misconception", "coverage-lab"], "objectives": ["3.2.1"], "questionKind": "choice", "options": ["95% of individual processing costs lie inside these endpoints.", "The fixed mean has a 95% frequentist probability of being inside these now-fixed endpoints.", "The interval came from a procedure that covers the fixed mean in 95% of repeated samples under the model."], "correct": 2, "feedback": ["A confidence interval for a mean does not estimate an interval containing 95% of individuals.", "That probability interpretation would require an additional model for the parameter; it is not this calculation.", "Yes. Coverage describes the procedure before observing a particular sample."]}, {"id": "ci-transfer", "type": "question", "prompt": "A manager wants both shorter intervals and higher confidence. Explain why changing confidence alone cannot achieve both, and identify one model-preserving way to improve precision.", "solution": "Higher confidence increases the quantile and therefore widens the interval at fixed n and \u03c3. Increasing the size of a genuinely independent representative sample reduces standard error and can offset that width increase. It does not repair selection bias.", "taughtIn": ["ci-width", "ci-model"], "objectives": ["3.2.1", "3.2.3.mean-known"], "questionKind": "written", "rubric": [{"text": "Link higher confidence to a larger quantile and greater width.", "marks": 2, "taughtIn": ["ci-width"]}, {"text": "Explain how increasing a valid sample size reduces standard error, without claiming bias is fixed.", "marks": 2, "taughtIn": ["ci-width", "ci-model"]}]}, {"id": "ci-readiness", "type": "callout", "title": "Choose a repair, then retry", "tone": "idea", "text": "If you described 95% of individual costs, return to \u201cWhere the 95% belongs\u201d. If you assigned 95% frequentist probability to the fixed mean after observing endpoints, revisit the random-endpoint derivation and coverage lab. If higher confidence made your interval narrower, revisit \u201cCoverage and precision answer different questions\u201d. Retry without the displayed formula: independent normal data have known \u03c3=10, n=25 and observed mean 50. Using z=1.96 gives SE=2 and interval [46.08,53.92]. Explain why quadrupling n halves the width while leaving the model\u2019s nominal coverage at 95%. Reading these endpoints is not evidence that you can reconstruct their derivation."}], "summary": ["A confidence interval is a random procedure before sampling and fixed endpoints after observation.", "The known-variance normal mean interval follows by rearranging a standard normal pivot.", "More confidence widens an interval; larger independent samples narrow it.", "The advertised coverage depends on the model and sampling plan."], "coverage": [{"objective": "3.2.1", "teaching": ["ci-model", "ci-misconception"], "practice": ["ci-interpret", "ci-transfer"]}, {"objective": "3.2.2.normal-known", "teaching": ["ci-pivot", "ci-derivation"], "practice": ["ci-calculate", "ci-reconstruct"]}, {"objective": "3.2.3.mean-known", "teaching": ["ci-formula", "ci-example", "ci-width"], "practice": ["ci-calculate", "ci-transfer"]}], "provenance": "Original prose, fictional situations, numerical designs, questions and interaction brief created independently for Open Actuary. The supplied 2019 syllabus identifies scope; no ActEd text, fictional case, exercise or diagram is reproduced.", "technicalNotes": ["Normal quantiles and endpoints are checked against independent reference values.", "Simulation counts are stochastic illustrations; the coverage probability follows from the pivot.", "Known variance and exact normality are maintained in this unit; no t or bootstrap claim is made."]}','2','{"revision": 2, "reviewer": "Independent teaching, interaction and browser reviewers; root recomputation and repair audit (2026-10-27)", "level": "pilot", "checks": {"technical": "Known-normal pivot, rearrangement, fixed-parameter/random-endpoint interpretation rechecked. New retry SE2 and endpoints46.08/53.92 independently calculated; structural/KaTeX checks pass.", "pedagogy": "Fresh teaching review identified outcome/practice gaps; independent final audit verifies repaired prompts actually elicit outcomes and every rubric criterion has earlier teaching. Readiness routes and non-overlapping credit checked. Agent review only, no learner trial.", "interaction": "Local browser at390px: n25\u2192100 visibly halves length15.68\u21927.84 on fixed57..143 scale; paired coverage49/50 unchanged. Geometric checks span all permitted n/confidence settings.", "accessibility": "Independent actual desktop/mobile browser QA: new practice text wraps without page overflow at390px; HTML chart labels12px; navigation targets focus and preserve controls; search/header checked320px. Text/table alternatives retained. No assistive-technology-user validation claimed.", "originality": "Original historical-syllabus pilot and independently developed new scenarios/teaching. Review used current course snapshots and independent arithmetic, without copying reference-book expression. No external similarity scan or human copyright certification claimed."}, "unresolved": [], "createdAt": "2026-10-27T16:39:04.011Z"}','2026-10-27T16:40:35.445Z','{"revision": 2, "reviewer": "Independent teaching, interaction and browser reviewers; root recomputation and repair audit (2026-10-27)", "level": "pilot", "checks": {"technical": "Known-normal pivot, rearrangement, fixed-parameter/random-endpoint interpretation rechecked. New retry SE2 and endpoints46.08/53.92 independently calculated; structural/KaTeX checks pass.", "pedagogy": "Fresh teaching review identified outcome/practice gaps; independent final audit verifies repaired prompts actually elicit outcomes and every rubric criterion has earlier teaching. Readiness routes and non-overlapping credit checked. Agent review only, no learner trial.", "interaction": "Local browser at390px: n25\u2192100 visibly halves length15.68\u21927.84 on fixed57..143 scale; paired coverage49/50 unchanged. Geometric checks span all permitted n/confidence settings.", "accessibility": "Independent actual desktop/mobile browser QA: new practice text wraps without page overflow at390px; HTML chart labels12px; navigation targets focus and preserve controls; search/header checked320px. Text/table alternatives retained. No assistive-technology-user validation claimed.", "originality": "Original historical-syllabus pilot and independently developed new scenarios/teaching. Review used current course snapshots and independent arithmetic, without copying reference-book expression. No external similarity scan or human copyright certification claimed."}, "unresolved": [], "createdAt": "2026-10-27T16:39:04.011Z"}');
